using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;
public static class Protected19 {
 static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});
 static string Id(Object o)=>o==null?"null":GlobalObjectId.GetGlobalObjectIdSlow(o).ToString();
 static string Normalize(string s)=>Regex.Replace(s,"\"instanceID\":(-?[0-9]+)",m=>"\"stableID\":\""+Id(EditorUtility.InstanceIDToObject(int.Parse(m.Groups[1].Value)))+"\"");
 static bool Protect(Component c)=>c is Collider||c is Rigidbody||c is Camera||c is Animator||(c is MonoBehaviour&&!(c is TMPro.TMP_Text)&&!(c is TMPro.TMP_SubMesh));
 public static object Main(string output){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit only");var all=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Component>(true)).Where(c=>c!=null&&Protect(c)).ToArray();var transforms=all.SelectMany(c=>c.GetComponentsInParent<Transform>(true)).Distinct().OrderBy(Id).ToArray();var d=all.OfType<Chapter45Director>().Single();var state=new{scene=SceneManager.GetActiveScene().path,route=Normalize(EditorJsonUtility.ToJson(d.route)),components=all.OrderBy(Id).Select(c=>new{id=Id(c),type=c.GetType().FullName,serialized=Normalize(EditorJsonUtility.ToJson(c))}).ToArray(),transforms=transforms.Select(t=>new{id=Id(t),parent=Id(t.parent),t.name,active=t.gameObject.activeSelf,position=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},rotation=new[]{t.localRotation.x,t.localRotation.y,t.localRotation.z,t.localRotation.w},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z}}).ToArray()};if(File.Exists(output))throw new Exception("Preserve snapshot");File.WriteAllText(output,Json(state));return new{path=output,components=all.Length,transforms=transforms.Length};}
}
